public boolean  validateDelete()
{
    boolean ok = next validateDelete();
    if (FeatureStateProvider::isFeatureEnabled(UPSGlobalEnableFeature::instance()))
    {
        UPSPricingAttributeLink  pricingAttributeLink;

        select firstonly RecId from pricingAttributeLink
                where pricingAttributeLink.AttributeName == this.Name
                && pricingAttributeLink.TypeName == enum2Str(this.getActualAttributeType().DataType)
                && pricingAttributeLink.PriceAttributeClassId == classNum(UPSPricingAttributeEcoResAttribute);

        if (pricingAttributeLink.RecId)
        {
            ok = checkFailed("@UnifiedPricingService:UPSErrorDeleteAttrValueOnPricingGroup");
        }
    }

    return ok;
}
